using System;using System.Linq;using System.Drawing;using System.Collections.Generic;
namespace GearLab {
 public static class MechanismCad {
  public static bool Finite(double x){return !double.IsNaN(x)&&!double.IsInfinity(x);}
  static double Cross(PointF a,PointF b,PointF c){return ((double)b.X-a.X)*(c.Y-a.Y)-((double)b.Y-a.Y)*(c.X-a.X);}
  public static bool SimplePolygon(PointF[] p){if(p==null||p.Length<3)return false;for(int i=0;i<p.Length;i++){int j=(i+1)%p.Length;if(CadLoop.Length(p[i],p[j])<1e-5)return false;for(int k=i+1;k<p.Length;k++){int l=(k+1)%p.Length;if(k==j||l==i)continue;double a=Cross(p[i],p[j],p[k]),b=Cross(p[i],p[j],p[l]),c=Cross(p[k],p[l],p[i]),d=Cross(p[k],p[l],p[j]);if(a*b<=0&&c*d<=0&&Math.Max(Math.Min(p[i].X,p[j].X),Math.Min(p[k].X,p[l].X))<=Math.Min(Math.Max(p[i].X,p[j].X),Math.Max(p[k].X,p[l].X))+1e-7&&Math.Max(Math.Min(p[i].Y,p[j].Y),Math.Min(p[k].Y,p[l].Y))<=Math.Min(Math.Max(p[i].Y,p[j].Y),Math.Max(p[k].Y,p[l].Y))+1e-7)return false;}}return Math.Abs(CadLoop.Area(p))>1e-5;}
  public static List<string> Validate(MechanismProject p){var errors=new List<string>();if(p.Parts.Count>150||p.Links.Count>200){errors.Add("Максимум 150 деталей и 200 связей.");return errors;}if(!Finite(p.InputRpm)||Math.Abs(p.InputRpm)>60000||!Finite(p.InputTorque)||p.InputTorque<0||p.InputTorque>1000000)errors.Add("Некорректные обороты или входной момент.");var ids=new HashSet<string>();foreach(var part in p.Parts){string name=part.Name??"Деталь";if(string.IsNullOrWhiteSpace(part.Id)||!ids.Add(part.Id))errors.Add("Повторяющийся идентификатор детали.");if(!new[]{"shaft","gear","pulley","bearing","block","sketch"}.Contains(part.Kind))errors.Add(name+": неизвестный тип.");foreach(var prop in typeof(MechanismPart).GetProperties().Where(a=>a.PropertyType==typeof(double)))if(!Finite((double)prop.GetValue(part,null)))errors.Add(name+": некорректное число "+prop.Name);if(new[]{part.X,part.Y,part.Z,part.OffsetZ}.Any(x=>Math.Abs(x)>10000)||Math.Abs(part.Angle)>360000)errors.Add(name+": положение вне диапазона ±10000 мм.");if(part.Length<.1||part.Length>2000||part.Bore<0||part.Diameter<.1||part.Diameter>2000||part.SizeX<.1||part.SizeY<.1||part.SizeX>2000||part.SizeY>2000||part.Density<=0||part.Density>100000||part.LoadTorque<0||part.LoadTorque>1000000)errors.Add(name+": недопустимые размеры, плотность или нагрузка.");if(part.Kind=="gear"&&(part.Teeth<8||part.Teeth>200||part.Module<.1||part.Module>10))errors.Add(name+": 8–200 зубьев, модуль 0,1–10 мм.");if(part.Holes==null||part.Steps==null||part.Outline==null){errors.Add(name+": повреждённые данные CAD.");continue;}if(part.Holes.Count>64||part.Steps.Count>64||part.Outline.Count>1000)errors.Add(name+": слишком много элементов CAD.");foreach(var hole in part.Holes)if(!Finite(hole.X)||!Finite(hole.Y)||!Finite(hole.Diameter)||!Finite(hole.Depth)||hole.Diameter<.1||hole.Depth<0||hole.Depth>(part.Kind=="shaft"?p.ShaftLength(part):part.Length)||Math.Abs(hole.X)>2000||Math.Abs(hole.Y)>2000)errors.Add(name+": некорректное отверстие или карман.");foreach(var step in part.Steps)if(!Finite(step.Length)||!Finite(step.Diameter)||!Finite(step.Bore)||step.Length<.1||step.Length>2000||step.Diameter<.1||step.Diameter>2000||step.Bore<0||step.Bore>=step.Diameter)errors.Add(name+": некорректная ступень вала.");if(part.Steps.Count>0&&part.Steps.Sum(s=>s.Length)>2000)errors.Add(name+": суммарная длина вала больше 2000 мм.");foreach(var v in part.Outline)if(!Finite(v.X)||!Finite(v.Y)||Math.Abs(v.X)>2000||Math.Abs(v.Y)>2000)errors.Add(name+": некорректная точка эскиза.");if(part.Kind=="sketch"&&errors.Count==0&&!SimplePolygon(part.Outline.Select(v=>new PointF((float)v.X,(float)v.Y)).ToArray()))errors.Add(name+": нужен замкнутый контур без самопересечений.");if(!string.IsNullOrEmpty(part.ShaftId)){var shaft=p.Find(part.ShaftId);if(part.Kind=="shaft"||shaft==null||shaft.Kind!="shaft")errors.Add(name+": некорректная посадка на вал.");else{double size=p.ShaftLength(shaft);if(part.OffsetZ<0||part.OffsetZ+part.Length>size+1e-6)errors.Add(name+": деталь выходит за длину вала.");double bore=p.ActualBore(part);if(bore+1e-6<p.ShaftDiameter(shaft,part.OffsetZ)||bore+1e-6<p.ShaftDiameter(shaft,part.OffsetZ+part.Length-1e-6))errors.Add(name+": вал не входит в посадочное отверстие.");if(shaft.Steps.Count>0){double z=0;foreach(var s in shaft.Steps){if(z+ s.Length>part.OffsetZ+1e-6&&z<part.OffsetZ+part.Length-1e-6&&s.Diameter>bore+1e-6)errors.Add(name+": посадка пересекает более толстую ступень вала.");z+=s.Length;}}}}}
   if(errors.Count>0)return errors;foreach(var part in p.Parts){try{var solid=BuildPart(p,part);CheckPart(solid,errors);}catch(Exception ex){errors.Add(part.Name+": "+ex.Message);}}return errors;
  }
  static CadLoop LocalOuter(MechanismPart p){if(p.Kind=="gear")return CadLoop.Polygon(Engine.Involute(p.Teeth,p.Module,false));if(p.Kind=="block")return CadLoop.Polygon(new[]{new PointF((float)-p.SizeX/2,(float)-p.SizeY/2),new PointF((float)p.SizeX/2,(float)-p.SizeY/2),new PointF((float)p.SizeX/2,(float)p.SizeY/2),new PointF((float)-p.SizeX/2,(float)p.SizeY/2)});if(p.Kind=="sketch")return CadLoop.Polygon(p.Outline.Select(v=>new PointF((float)v.X,(float)v.Y)).ToArray());return CadLoop.Round(0,0,p.Diameter/2);}
  static CadLoop Place(CadLoop loop,double x,double y,double angle){return loop.Circle?CadLoop.Round(x+loop.X*Math.Cos(angle)-loop.Y*Math.Sin(angle),y+loop.X*Math.Sin(angle)+loop.Y*Math.Cos(angle),loop.R):CadLoop.Polygon(Engine.Transform(loop.Points,x,y,angle));}
  static Color Colour(string kind){switch(kind){case "shaft":return Color.FromArgb(142,159,180);case "gear":return Color.FromArgb(232,164,68);case "pulley":return Color.FromArgb(70,166,150);case "bearing":return Color.FromArgb(114,135,166);case "block":return Color.FromArgb(85,153,201);default:return Color.FromArgb(172,129,201);}}
  public static CadPart BuildPart(MechanismProject project,MechanismPart p){if(p.NativeStep!=null)return MechanismNative.Part(project,p);string role=p.Kind=="shaft"?"shaft":p.Kind=="gear"||p.Kind=="pulley"?"gear":p.Kind=="bearing"?"bearing":"housing";var part=new CadPart(p.Id,p.Name,role,Colour(p.Kind));var xyz=project.Position(p);double angle=p.Angle*Math.PI/180,bore=project.ActualBore(p),height=p.Kind=="shaft"?project.ShaftLength(p):p.Length;var sections=new List<CadSection>();if(p.Kind=="shaft"&&p.Steps.Count>0){double z=0;foreach(var s in p.Steps){sections.Add(new CadSection(z,z+s.Length,CadLoop.Round(0,0,s.Diameter/2),s.Bore>0?new[]{CadLoop.Round(0,0,s.Bore/2)}:null));z+=s.Length;}}else sections.Add(new CadSection(0,height,LocalOuter(p),bore>0?new[]{CadLoop.Round(0,0,bore/2)}:null));foreach(var s in sections){var levels=new SortedSet<double>{s.Bottom,s.Top};foreach(var h in p.Holes)if(h.Depth>0){double start=height-h.Depth;if(start>s.Bottom+1e-8&&start<s.Top-1e-8)levels.Add(start);}var stops=levels.ToArray();for(int j=1;j<stops.Length;j++){double bottom=stops[j-1],top=stops[j];var holes=s.Holes.ToList();foreach(var h in p.Holes)if(h.Depth==0||bottom>=height-h.Depth-1e-8)holes.Add(CadLoop.Round(h.X,h.Y,h.Diameter/2));part.Sections.Add(new CadSection(xyz[2]+bottom,xyz[2]+top,Place(s.Outer,xyz[0],xyz[1],angle),holes.Select(h=>Place(h,xyz[0],xyz[1],angle))));}}return part;}
  static double PointSegment(double x,double y,PointF a,PointF b){double dx=(double)b.X-a.X,dy=(double)b.Y-a.Y,t=Math.Max(0,Math.Min(1,((x-a.X)*dx+(y-a.Y)*dy)/(dx*dx+dy*dy)));return Math.Sqrt(Math.Pow(x-a.X-dx*t,2)+Math.Pow(y-a.Y-dy*t,2));}
  static void CheckPart(CadPart part,List<string> errors){if(part.Volume()<=1e-7)errors.Add(part.Label+": нулевой объём.");foreach(var s in part.Sections){foreach(var h in s.Holes){bool within;if(s.Outer.Circle)within=Math.Sqrt(Math.Pow(h.X-s.Outer.X,2)+Math.Pow(h.Y-s.Outer.Y,2))+h.R<s.Outer.R-1e-5;else within=s.Outer.Contains(h.X,h.Y)&&Enumerable.Range(0,s.Outer.Points.Length).All(i=>PointSegment(h.X,h.Y,s.Outer.Points[i],s.Outer.Points[(i+1)%s.Outer.Points.Length])>h.R+1e-5);if(!within)errors.Add(part.Label+": отверстие выходит за материал; открытые пазы этим инструментом не создаются.");}for(int i=0;i<s.Holes.Count;i++)for(int j=i+1;j<s.Holes.Count;j++){var a=s.Holes[i];var b=s.Holes[j];if(Math.Sqrt(Math.Pow(a.X-b.X,2)+Math.Pow(a.Y-b.Y,2))<=a.R+b.R+1e-5)errors.Add(part.Label+": отверстия пересекаются или касаются. Измените диаметр/положение существующего отверстия.");}}}
  static CadLoop BeltLoop(double r1,double r2,double distance,double x,double y,double direction){double a=Math.Acos((r1-r2)/distance);var points=new List<PointF>();for(int i=0;i<=64;i++){double t=a+(Engine.Tau-2*a)*i/64;points.Add(new PointF((float)(r1*Math.Cos(t)),(float)(r1*Math.Sin(t))));}for(int i=0;i<=64;i++){double t=Engine.Tau-a+2*a*i/64;points.Add(new PointF((float)(distance+r2*Math.Cos(t)),(float)(r2*Math.Sin(t))));}return CadLoop.Polygon(Engine.Transform(points.ToArray(),x,y,direction));}
  public static CadAssembly Build(MechanismProject p){var m=new CadAssembly();m.Errors.AddRange(Validate(p));if(m.Errors.Count>0)return m;foreach(var part in p.Parts)m.Parts.Add(BuildPart(p,part));foreach(var link in p.Links.Where(l=>l.Kind=="belt")){var a=p.Find(link.FromId);var b=p.Find(link.ToId);if(a==null||b==null||a.Kind!="pulley"||b.Kind!="pulley")continue;var x=p.Position(a);var y=p.Position(b);double d=Math.Sqrt(Math.Pow(y[0]-x[0],2)+Math.Pow(y[1]-x[1],2)),angle=Math.Atan2(y[1]-x[1],y[0]-x[0]),lo=Math.Max(x[2],y[2]),hi=Math.Min(x[2]+a.Length,y[2]+b.Length);if(d<=(a.Diameter+b.Diameter)/2+.1||hi-lo<.1)continue;var outer=BeltLoop(a.Diameter/2+2,b.Diameter/2+2,d,x[0],x[1],angle);var inner=BeltLoop(a.Diameter/2+.05,b.Diameter/2+.05,d,x[0],x[1],angle);var belt=new CadPart("BELT_"+link.Id,"Ремень: габарит без расчёта натяжения","belt",Color.FromArgb(63,72,84)){Reference=true};belt.Sections.Add(new CadSection(lo,hi,outer,new[]{inner}));m.Parts.Add(belt);}return m;}
  public static void ArrangeLink(MechanismProject p,MechanismLink link){var a=p.Find(link.FromId);var b=p.Find(link.ToId);var sa=p.Shaft(a);var sb=p.Shaft(b);if(a==null||b==null||sa==null||sb==null||sa==sb)throw new Exception("Для связи нужны детали на двух разных валах.");var pos=p.Position(a);double distance=link.Kind=="gear"?(a.PitchDiameter+b.PitchDiameter)/2:link.Kind=="belt"?(a.PitchDiameter+b.PitchDiameter)*.8+25:0,phi=link.PlacementAngle*Math.PI/180;sb.X=pos[0]+distance*Math.Cos(phi);sb.Y=pos[1]+distance*Math.Sin(phi);if(link.Kind!="coupling"){sb.Z=pos[2]+a.Length/2-b.OffsetZ-b.Length/2;if(link.Kind=="gear")b.Angle=((a.Teeth+b.Teeth)*phi+b.Teeth*Math.PI-Math.PI-a.Teeth*a.Angle*Math.PI/180)/b.Teeth*180/Math.PI;}else sb.Z=sa.Z+p.ShaftLength(sa);}
  public static void AutoArrange(MechanismProject p){var placed=new HashSet<string>();foreach(var link in p.Links){var target=p.Shaft(p.Find(link.ToId));if(target!=null&&!placed.Add(target.Id))throw new Exception("У ведомого вала несколько входящих связей: расставьте его вручную.");ArrangeLink(p,link);}}
  public static Result ViewResult(MechanismProject p,MechanismSolution solution,CadAssembly model){return new Result{P=new Parameters{Kind=9},Model=model,Mechanism=p,MechanismSolution=solution};}
 }
}
